INSERT INTO `factors` (`id`, `name`, `type`, `response`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 'Time', 'perception', '{"points":10784,"testCount":210}', '2024-04-24 09:18:51', '2025-09-19 15:47:56', NULL),
	(2, 'Health', 'perception', '{"points":5446,"testCount":210}', '2024-04-24 09:18:51', '2025-09-19 15:47:56', NULL),
	(3, 'Aging', 'perception', '{"points":8735,"testCount":210}', '2024-04-24 09:18:51', '2025-09-19 15:47:56', NULL),
