	(55, 'I am a lucky person.', 'Jestem szczÄ™Å›liwym czÅ‚owiekiem.', 'Ich bin ein glÃ¼cklicher Mensch.', 'Sou uma pessoa sortuda.', 'Soy una persona afortunada.', 'Je suis une personne chanceuse.', 'Sono una persona fortunata.', 'forward', 'question55_answer_id', 4, 6, '2024-04-24 09:18:52', '2024-04-24 09:18:52', NULL),
